const data = $input.first().json;
let userMessage = '';
let chatId = '';
let firstName = '';
let callbackType = 'text';
let callbackData = null;
let skipAI = false;
let templateText = '';
let templateMarkup = '';
let callbackMessageId = null;

if (data.callback_query) {
  chatId = String(data.callback_query.message.chat.id);
  firstName = data.callback_query.from.first_name || '';
  callbackData = data.callback_query.data;
  callbackMessageId = data.callback_query.message.message_id;

  if (callbackData === 'noop') {
    skipAI = true;
    callbackType = 'noop';
  } else {
    const callbackMap = {
      'new_booking': 'Хочу записаться на услугу',
      'show_services': 'Покажи все услуги и цены',
      'contact_us': 'Как с вами связаться',
      'service_tire': 'Интересует шиномонтаж и балансировка колёс',
      'service_oil': 'Нужна замена масла',
      'service_brakes': 'Нужна замена тормозных колодок',
      'service_repair': 'Нужен мелкий ремонт'
    };
    if (callbackMap[callbackData]) {
      callbackType = callbackData;
      userMessage = callbackMap[callbackData];
    } else {
      callbackType = 'callback';
      userMessage = callbackData;
    }
  }
} else if (data.message) {
  chatId = String(data.message.chat.id);
  firstName = data.message.from.first_name || '';
  userMessage = data.message.text || '/start';
}

// Payment receipt detection (before template check)
let isPaymentReceipt = false;
let pendingBookingData = null;

if (chatId) {
  const isPhoto = !!(data.message && data.message.photo && data.message.photo.length > 0);
  const isDocument = !!(data.message && data.message.document);
  const staticData = $getWorkflowStaticData('global');
  const pending = staticData['payment_' + chatId];
  if (pending && (isPhoto || isDocument || /оплат|чек|перевел|перевела|готов|done|paid/i.test(userMessage))) {
    isPaymentReceipt = true;
    pendingBookingData = pending;
    skipAI = true;
  }
}

const templates = {
  '_start': {
    text: '👋 Здравствуйте! Я помогу записаться на техническое обслуживание автомобиля.\n\nВыберите услугу или напишите вопрос:',
    buttons: [
      [{ "text": "🔧 Шиномонтаж и балансировка", "callback_data": "service_tire" }],
      [{ "text": "🛢 Замена масла", "callback_data": "service_oil" }],
      [{ "text": "🔩 Тормозные колодки", "callback_data": "service_brakes" }],
      [{ "text": "🚗 Мелкий ремонт", "callback_data": "service_repair" }],
      [{ "text": "📋 Все услуги и цены", "callback_data": "show_services" }]
    ]
  },
  'contact_us': {
    text: '📞 Свяжитесь с нами:\n\nТелефон: +7 711 463 6644\nРабочие часы: Пн-Сб 9:00-20:00\n\nИли напишите нам здесь!',
    buttons: [
      [{ "text": "📅 Записаться онлайн", "callback_data": "new_booking" }]
    ]
  }
};

let templateKey = '';
if (!isPaymentReceipt) {
  if (userMessage === '/start') {
    templateKey = '_start';
  } else if (templates[callbackType]) {
    templateKey = callbackType;
  }
}

if (templateKey) {
  skipAI = true;
  const t = templates[templateKey];
  templateText = t.text;
  templateMarkup = JSON.stringify({ inline_keyboard: t.buttons });
}

return {
  json: { userMessage, chatId, firstName, callbackType, callbackData, skipAI, templateText, templateMarkup, callbackMessageId, isPaymentReceipt, pendingBookingData }
};

const data = $('Podgotovka vvoda').first().json;
const chatId = data.chatId;
const pendingData = data.pendingBookingData;

// Demo: always verify successfully, clear from static data
const staticData = $getWorkflowStaticData('global');
delete staticData['payment_' + chatId];

if (!pendingData) {
  return { json: {
    chatId: chatId || '',
    clientName: '', clientPhone: '', serviceName: '',
    bookingDate: '', bookingTime: '', carInfo: '',
    startISO: '', endISO: '', paymentVerified: false
  }};
}

return { json: {
  chatId,
  clientName: pendingData.clientName || '',
  clientPhone: pendingData.clientPhone || '',
  serviceName: pendingData.serviceName || '',
  bookingDate: pendingData.bookingDate || '',
  bookingTime: pendingData.bookingTime || '',
  carInfo: pendingData.carInfo || '',
  startISO: pendingData.startISO || '',
  endISO: pendingData.endISO || '',
  paymentVerified: true
}};

return JSON.stringify({
  services: [
    { id: 1, name: 'Балансировка колёс', price: '2 500 тг/колесо (4 шт — 10 000 тг)', duration_min: 30 },
    { id: 2, name: 'Шиномонтаж сезонный (4 шт)', price: '6 000 тг', duration_min: 45 },
    { id: 3, name: 'Замена масла (без стоимости масла)', price: '3 000 тг', duration_min: 30 },
    { id: 4, name: 'Замена тормозных колодок (за ось)', price: '4 000 тг', duration_min: 30 },
    { id: 5, name: 'Развал-схождение', price: '5 000 тг', duration_min: 45 },
    { id: 6, name: 'Диагностика двигателя', price: '5 000 тг', duration_min: 60 },
    { id: 7, name: 'Замена воздушного фильтра', price: '1 500 тг + стоимость фильтра', duration_min: 15 },
    { id: 8, name: 'Замена свечей зажигания', price: '2 000 тг + стоимость свечей', duration_min: 30 },
    { id: 9, name: 'Промывка инжектора', price: '8 000 тг', duration_min: 60 },
    { id: 10, name: 'Мелкий кузовной ремонт', price: 'от 15 000 тг', duration_min: 120 }
  ],
  working_hours: 'Пн-Сб: 9:00-20:00, Вс: выходной',
  slot_interval_min: 30
});

// Parameters may or may not be injected depending on n8n version
// Always return success - AI holds all booking data in session memory
// and will format the confirmation message itself
let svc = '', nm = '', ph = '';
try { if (typeof service_name !== 'undefined' && service_name) svc = String(service_name); } catch(e) {}
try { if (typeof client_name !== 'undefined' && client_name) nm = String(client_name); } catch(e) {}
try { if (typeof client_phone !== 'undefined' && client_phone) ph = String(client_phone); } catch(e) {}

const id = 'STO-' + String(Date.now()).slice(-6);
const info = [svc, nm, ph].filter(x => x).join(', ');
return 'OK: Запись ' + id + ' зарегистрирована.' + (info ? ' Клиент: ' + info + '.' : '');

const aiResponse = $input.first().json.output;
const prepData = $('Podgotovka vvoda').first().json;
const chatId = prepData.chatId;
const callbackType = prepData.callbackType || 'text';
let text = aiResponse || 'Произошла ошибка. Попробуйте ещё раз.';
text = text.replace(/[*`[\]]/g, '').replace(/_+/g, ' ').replace(/ {2,}/g, ' ');
let isBooking = false, clientName = '', clientPhone = '', serviceName = '', bookingDate = '', bookingTime = '', carInfo = '', startISO = '', endISO = '';
const tl = text.toLowerCase();
if (tl.includes('запись подтверждена') || tl.includes('жазба расталды')) {
  isBooking = true;
  var nm = text.match(/Клиент[:\s]+([^\n]+)/i);
  var ph = text.match(/Телефон[:\s]+([^\n]+)/i);
  var sv = text.match(/Услуга[:\s]+([^\n]+)/i);
  var dt = text.match(/Дата[:\s]+([^\n]+)/i);
  var tm = text.match(/Время[:\s]+([^\n]+)/i);
  var cr = text.match(/Авто[:\s]+([^\n]+)/i);
  clientName = nm ? nm[1].trim() : '';
  clientPhone = ph ? ph[1].trim() : '';
  serviceName = sv ? sv[1].trim() : '';
  bookingDate = dt ? dt[1].trim() : '';
  bookingTime = tm ? tm[1].trim() : '';
  carInfo = cr ? cr[1].replace(/\s*(Ждём|Мастер|Запись).*/i, '').trim() : '';
  if (bookingDate && bookingTime) {
    var dn = bookingDate; var dp = bookingDate.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
    if (dp) dn = dp[3] + '-' + dp[2].padStart(2,'0') + '-' + dp[1].padStart(2,'0');
    var tp = bookingTime.match(/(\d{1,2}):(\d{2})/); var tn = tp ? tp[1].padStart(2,'0') + ':' + tp[2] : bookingTime;
    startISO = dn + 'T' + tn + ':00+05:00';
    var tpParts = tn.split(':');
    var endH = String(parseInt(tpParts[0]) + 1).padStart(2, '0');
    endISO = dn + 'T' + endH + ':' + tpParts[1] + ':00+05:00';
  }
}
if (isBooking) {
  text = text.replace(/Запись подтверждена!?\s*/i, '').trim();
  text = text.replace(/\nЖдём вас![^\n]*/i, '').replace(/Ждём вас![^\n]*/i, '').trim();
  text = text.replace(/Жазба расталды!?\s*/i, '').trim();
  text = text.replace(/^[\s\n]+/, '').trim();
}
var btns = [];
if (isBooking) { btns = [[{text:'⏳ Ожидаем оплату...',callback_data:'noop'}]]; }
else if (callbackType==='contact_us') { btns = [[{text:'📅 Записаться',callback_data:'new_booking'}]]; }
else if (tl.includes('здравствуйт') || tl.includes('салам')) { btns = [[{text:'📋 Все услуги',callback_data:'show_services'}]]; }
else { btns = [[{text:'🔄 Другая услуга',callback_data:'new_booking'}],[{text:'📞 Контакты',callback_data:'contact_us'}]]; }
return { json: { chat_id: chatId, text: text.trim(), reply_markup: {inline_keyboard: btns}, isBooking, clientName, clientPhone, serviceName, bookingDate, bookingTime, carInfo, startISO, endISO } };

const formData = $('Formatirovanie otveta').first().json;
const chatId = $('Podgotovka vvoda').first().json.chatId;

const bookingData = {
  clientName: formData.clientName || '',
  clientPhone: formData.clientPhone || '',
  serviceName: formData.serviceName || '',
  bookingDate: formData.bookingDate || '',
  bookingTime: formData.bookingTime || '',
  carInfo: formData.carInfo || '',
  startISO: formData.startISO || '',
  endISO: formData.endISO || ''
};

const staticData = $getWorkflowStaticData('global');
staticData['payment_' + chatId] = bookingData;

return { json: { chatId, bookingData, saved: true } };
